"use client";

import React, { useState, useMemo, useRef } from "react";
import { 
  Calendar as CalendarIcon, 
  Clock, 
  CheckCircle2, 
  AlertTriangle, 
  Plane, 
  Stethoscope, 
  Briefcase, 
  Baby, 
  Umbrella, 
  GraduationCap, 
  Heart, 
  AlertOctagon,
  ChevronRight,
  Info,
  Sun,
  Moon,
  Trash2,
  RefreshCcw
} from "lucide-react";

// --- 1. FULL SUITE OF LEAVE TYPES ---
const LEAVE_TYPES = [
  { id: "annual", label: "Annual Leave", icon: Plane, balance: 18, color: "text-blue-600", bg: "bg-blue-50", desc: "Vacation & Personal time" },
  { id: "sick", label: "Sick Leave", icon: Stethoscope, balance: 12, color: "text-rose-600", bg: "bg-rose-50", desc: "Medical illness", requiresDoc: true },
  { id: "casual", label: "Casual Leave", icon: Umbrella, balance: 6, color: "text-amber-600", bg: "bg-amber-50", desc: "Urgent personal matters" },
  { id: "comp_off", label: "Compensatory Off", icon: RefreshCcw, balance: 3, color: "text-emerald-600", bg: "bg-emerald-50", desc: "Overtime compensation" },
  { id: "maternity", label: "Maternity/Paternity", icon: Baby, balance: 90, color: "text-purple-600", bg: "bg-purple-50", desc: "Parental bonding", requiresDoc: true },
  { id: "bereavement", label: "Bereavement", icon: Heart, balance: 5, color: "text-slate-600", bg: "bg-slate-100", desc: "Loss of family member" },
  { id: "study", label: "Sabbatical / Study", icon: GraduationCap, balance: 0, color: "text-indigo-600", bg: "bg-indigo-50", desc: "Long term leave" },
  { id: "unpaid", label: "Loss of Pay (L.O.P)", icon: AlertOctagon, balance: 0, color: "text-red-600", bg: "bg-red-50", desc: "Unpaid absence" },
];

const HOLIDAYS = ["2026-01-26"]; // Republic Day
const TEAM_OUT = [{ date: "2026-01-20", name: "Sarah" }];

export default function EliteAbsencePortal() {
  // --- STATE ---
  const [mode, setMode] = useState<"single" | "range">("range"); // EXPLICT MODE SWITCHER
  const [range, setRange] = useState<{ start: string; end: string }>({ start: "", end: "" });
  const [typeId, setTypeId] = useState("annual");
  const [reason, setReason] = useState("");
  const [halfDay, setHalfDay] = useState<"am" | "pm" | null>(null);
  const [file, setFile] = useState<File | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- LOGIC: DATE HANDLING ---
  const handleDateClick = (dateStr: string) => {
    if (mode === "single") {
      // Single Mode: Start and End are same
      setRange({ start: dateStr, end: dateStr });
      setHalfDay(null); // Reset half day
    } else {
      // Range Mode logic
      if (!range.start || (range.start && range.end)) {
        setRange({ start: dateStr, end: "" }); // Start fresh
      } else {
        const s = new Date(range.start);
        const e = new Date(dateStr);
        if (e < s) setRange({ start: dateStr, end: "" }); // Clicked before start? Reset.
        else setRange({ ...range, end: dateStr });
      }
    }
  };

  // --- LOGIC: CALCULATOR ---
  const stats = useMemo(() => {
    if (!range.start || !range.end) return { total: 0, deduction: 0, weekends: 0, holidays: 0, conflict: false };
    
    let total = 0, deduction = 0, weekends = 0, holidays = 0, conflict = false;
    let cur = new Date(range.start);
    let end = new Date(range.end);

    while (cur <= end) {
      const dStr = cur.toISOString().split('T')[0];
      const day = cur.getDay();
      
      total++;
      if (HOLIDAYS.includes(dStr)) holidays++;
      else if (day === 0 || day === 6) weekends++;
      else {
        // If single day & half day selected, add 0.5, else 1
        deduction += (range.start === range.end && halfDay) ? 0.5 : 1;
        if (TEAM_OUT.some(t => t.date === dStr)) conflict = true;
      }
      cur.setDate(cur.getDate() + 1);
    }
    return { total, deduction, weekends, holidays, conflict };
  }, [range, halfDay]);

  const selectedType = LEAVE_TYPES.find(t => t.id === typeId)!;

  return (
    <div className="h-screen flex flex-col bg-[#F8FAFC] font-sans text-slate-800 overflow-hidden">
      
      {/* 1. HEADER */}
      <header className="flex-none px-6 py-4 bg-white border-b border-slate-200 flex items-center justify-between z-10">
        <div className="flex items-center gap-3">
           <div className="bg-slate-900 text-white p-2 rounded-lg"><CalendarIcon className="h-5 w-5" /></div>
           <h1 className="text-xl font-bold text-slate-900">Request Absence</h1>
        </div>
        <div className="flex items-center gap-4 text-xs font-bold text-slate-500">
           <span className="hidden md:inline">Balance: {selectedType.balance} Days</span>
           <div className="h-8 w-8 bg-blue-100 text-blue-700 rounded-full flex items-center justify-center">JD</div>
        </div>
      </header>

      {/* 2. THREE-COLUMN LAYOUT */}
      <div className="flex-1 grid grid-cols-12 overflow-hidden">
        
        {/* LEFT: LEAVE TYPES (Scrollable) */}
        <div className="col-span-3 lg:col-span-3 border-r border-slate-200 bg-white flex flex-col overflow-y-auto">
           <div className="p-4 bg-slate-50 border-b border-slate-100">
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Select Category</p>
           </div>
           <div className="p-2 space-y-1">
              {LEAVE_TYPES.map(t => (
                 <button 
                   key={t.id}
                   onClick={() => setTypeId(t.id)}
                   className={`w-full text-left p-3 rounded-xl flex items-start gap-3 transition-all ${typeId === t.id ? "bg-blue-50 ring-1 ring-blue-500/20" : "hover:bg-slate-50"}`}
                 >
                    <div className={`mt-0.5 p-1.5 rounded-lg ${t.bg} ${t.color} shrink-0`}>
                       <t.icon className="h-4 w-4" />
                    </div>
                    <div>
                       <div className="flex items-center justify-between w-full">
                          <p className={`text-xs font-bold ${typeId === t.id ? "text-slate-900" : "text-slate-600"}`}>{t.label}</p>
                          {typeId === t.id && <CheckCircle2 className="h-3 w-3 text-blue-600 ml-2" />}
                       </div>
                       <p className="text-[10px] text-slate-400 mt-0.5">{t.desc}</p>
                       <p className="text-[10px] font-bold text-slate-900 mt-1">{t.balance} Available</p>
                    </div>
                 </button>
              ))}
           </div>
        </div>

        {/* CENTER: CALENDAR (The Stage) */}
        <div className="col-span-5 lg:col-span-6 bg-slate-50/50 p-6 flex flex-col relative">
           
           {/* MODE SWITCHER (The Fix for Confusion) */}
           <div className="flex justify-center mb-6">
              <div className="bg-white p-1 rounded-xl shadow-sm border border-slate-200 inline-flex">
                 <button 
                   onClick={() => { setMode("single"); setRange({start:"", end:""}); }}
                   className={`px-6 py-2 rounded-lg text-xs font-bold transition-all ${mode === "single" ? "bg-slate-900 text-white shadow-md" : "text-slate-500 hover:bg-slate-50"}`}
                 >
                    Single Date
                 </button>
                 <button 
                   onClick={() => { setMode("range"); setRange({start:"", end:""}); }}
                   className={`px-6 py-2 rounded-lg text-xs font-bold transition-all ${mode === "range" ? "bg-slate-900 text-white shadow-md" : "text-slate-500 hover:bg-slate-50"}`}
                 >
                    Date Range
                 </button>
              </div>
           </div>

           {/* CALENDAR HEADER */}
           <div className="flex items-center justify-between mb-4 px-2">
              <h2 className="text-xl font-bold text-slate-800">January 2026</h2>
              {range.start && (
                 <button onClick={() => setRange({start:"", end:""})} className="text-xs font-bold text-rose-500 flex items-center gap-1 hover:bg-rose-50 px-2 py-1 rounded">
                    <Trash2 className="h-3 w-3" /> Clear
                 </button>
              )}
           </div>

           {/* GRID */}
           <div className="flex-1 bg-white rounded-2xl border border-slate-200 shadow-sm p-6 overflow-y-auto">
              <div className="grid grid-cols-7 gap-2">
                 {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map(d => (
                    <div key={d} className="text-center text-[10px] font-black text-slate-300 uppercase mb-2">{d}</div>
                 ))}
                 {[null, null, null].map((_, i) => <div key={`e-${i}`} />)} {/* Jan 1 is Thu */}

                 {Array.from({ length: 31 }).map((_, i) => {
                    const day = i + 1;
                    const dateStr = `2026-01-${day < 10 ? `0${day}` : day}`;
                    const isHoliday = HOLIDAYS.includes(dateStr);
                    const isWeekend = new Date(2026, 0, day).getDay() % 6 === 0;
                    
                    const isSelected = range.start === dateStr || range.end === dateStr;
                    const inRange = range.start && range.end && dateStr > range.start && dateStr < range.end;

                    return (
                       <button
                         key={day}
                         onClick={() => handleDateClick(dateStr)}
                         className={`
                           h-14 rounded-lg text-sm font-bold relative border transition-all
                           ${isSelected ? "bg-blue-600 text-white border-blue-600 z-10 scale-105 shadow-md" : ""}
                           ${inRange ? "bg-blue-50 text-blue-600 border-blue-50" : ""}
                           ${!isSelected && !inRange && isHoliday ? "bg-orange-50 text-orange-600 border-orange-100" : ""}
                           ${!isSelected && !inRange && isWeekend ? "bg-slate-50 text-slate-300 border-transparent" : "bg-white border-slate-100 hover:border-blue-400"}
                         `}
                       >
                          {day}
                          {isHoliday && !inRange && <span className="absolute bottom-1 right-1 h-1.5 w-1.5 rounded-full bg-orange-400"/>}
                       </button>
                    )
                 })}
              </div>
           </div>
        </div>

        {/* RIGHT: DETAILS PANEL (Context Aware) */}
        <div className="col-span-4 lg:col-span-3 bg-white border-l border-slate-200 flex flex-col overflow-y-auto">
           
           {/* SECTION A: SUMMARY */}
           <div className="p-6 border-b border-slate-100 bg-slate-50/50">
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400 mb-4">Request Summary</p>
              
              <div className="flex items-center gap-3 mb-4">
                 <div className={`p-2 rounded-lg ${selectedType.bg} ${selectedType.color}`}><selectedType.icon className="h-5 w-5"/></div>
                 <div>
                    <p className="text-sm font-bold text-slate-900">{selectedType.label}</p>
                    <p className="text-[10px] text-slate-400">{selectedType.desc}</p>
                 </div>
              </div>

              <div className="space-y-2 bg-white p-3 rounded-xl border border-slate-200">
                 <div className="flex justify-between text-xs">
                    <span className="text-slate-500">Selected Range</span>
                    <span className="font-bold text-slate-900">{range.start ? `${range.start.slice(5)} ${range.end ? '-> ' + range.end.slice(5) : ''}` : '-'}</span>
                 </div>
                 <div className="flex justify-between text-xs">
                    <span className="text-slate-500">Non-working Days</span>
                    <span className="font-bold text-slate-900">{stats.weekends + stats.holidays}</span>
                 </div>
                 <div className="pt-2 border-t border-slate-100 flex justify-between items-center">
                    <span className="text-xs font-bold text-slate-500">Total Deduction</span>
                    <span className="text-lg font-black text-blue-600">{stats.deduction} Days</span>
                 </div>
              </div>
           </div>

           {/* SECTION B: CONTEXTUAL INPUTS */}
           <div className="p-6 space-y-6 flex-1">
              
              {/* 1. HALF DAY TOGGLE (Only if Single Day) */}
              {mode === "single" && range.start && (
                 <div className="animate-in slide-in-from-top-2">
                    <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Duration</label>
                    <div className="grid grid-cols-3 gap-2 bg-slate-100 p-1 rounded-lg">
                       <button onClick={() => setHalfDay(null)} className={`py-2 text-[10px] font-bold rounded-md ${!halfDay ? "bg-white shadow text-blue-600" : "text-slate-400"}`}>Full Day</button>
                       <button onClick={() => setHalfDay("am")} className={`py-2 text-[10px] font-bold rounded-md flex items-center justify-center gap-1 ${halfDay === "am" ? "bg-white shadow text-blue-600" : "text-slate-400"}`}><Sun className="h-3 w-3"/> 1st Half</button>
                       <button onClick={() => setHalfDay("pm")} className={`py-2 text-[10px] font-bold rounded-md flex items-center justify-center gap-1 ${halfDay === "pm" ? "bg-white shadow text-blue-600" : "text-slate-400"}`}><Moon className="h-3 w-3"/> 2nd Half</button>
                    </div>
                 </div>
              )}

              {/* 2. REASON */}
              <div>
                 <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block">Reason</label>
                 <textarea 
                   className="w-full h-24 p-3 text-xs font-medium border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none resize-none" 
                   placeholder="Describe reason..."
                   value={reason}
                   onChange={(e) => setReason(e.target.value)}
                 />
              </div>

              {/* 3. ATTACHMENT (Conditional) */}
              {selectedType.requiresDoc && (
                 <div className="animate-in zoom-in-95">
                    <label className="text-[10px] font-bold uppercase text-slate-400 mb-2 block flex justify-between">
                       <span>Document</span>
                       <span className="text-rose-500">* Required</span>
                    </label>
                    <div 
                      onClick={() => fileInputRef.current?.click()}
                      className={`border-2 border-dashed rounded-xl h-20 flex flex-col items-center justify-center cursor-pointer transition-colors ${file ? "border-emerald-500 bg-emerald-50" : "border-slate-200 hover:border-blue-400"}`}
                    >
                       <input type="file" className="hidden" ref={fileInputRef} onChange={(e) => e.target.files && setFile(e.target.files[0])} />
                       {file ? (
                          <span className="text-xs font-bold text-emerald-600 flex items-center gap-1"><CheckCircle2 className="h-4 w-4"/> {file.name}</span>
                       ) : (
                          <span className="text-[10px] font-bold text-slate-400">Click to upload proof</span>
                       )}
                    </div>
                 </div>
              )}
           </div>

           {/* SECTION C: SUBMIT */}
           <div className="p-6 border-t border-slate-100 bg-slate-50">
              <button 
                disabled={!range.start || (selectedType.requiresDoc && !file)}
                className="w-full bg-slate-900 text-white py-4 rounded-xl font-bold text-sm hover:bg-black disabled:bg-slate-300 transition-all shadow-lg disabled:shadow-none"
              >
                 {range.start ? "Submit Request" : "Select Dates"}
              </button>
           </div>
        </div>

      </div>
    </div>
  );
}